import sys,numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot(); o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True)
for k,v in o.last.items(): Image.fromarray(v).save(f'/app/output/ready_{k}.png')
for k,v in o.last_depth.items(): np.save(f'/app/output/ready_{k}_depth.npy',v)
for cam, arr in o.last_depth.items():
 print(cam, np.histogram(arr, bins=np.arange(0,1.01,.05))[0])
for p in [(512,512),(100,100),(900,900)]: print('canvas',p,o.last['canvas_cam'][p],o.last_depth['canvas_cam'][p])
print('tip',o.meta['proprio']['now'][7:14])
